def resolve_iata(text: str) -> str:
    """
    Given a city/airport name (possibly with extra words), return the
    3-letter IATA code from AIRPORT_IATA_MAP.
    Tries longest match first to avoid 'new' matching before 'new york'.
    Falls back to the original normalized text if no match is found.
    """
    normalized = text.strip().lower()
    
    # Strip common form noise often captured in AWB boxes
    noise_words = [
        'airport', 'department', 'departure', 'destination', 'requested', 
        'routing', 'carrier', 'first', 'first carrier', 'addr.', 'of', 'and'
    ]
    for word in noise_words:
        normalized = re.sub(rf'\b{word}\b', '', normalized, flags=re.IGNORECASE)
    normalized = normalized.strip()

    # Sort keys longest-first so multi-word names match before substrings
    # We use \b to ensure we match whole words only (e.g., 'MAA' won't match 'MAAD')
    for key in sorted(AIRPORT_IATA_MAP.keys(), key=len, reverse=True):
        clean_key = key.lower().strip()
        pattern = rf'\b{re.escape(clean_key)}\b'
        if re.search(pattern, normalized):
            return AIRPORT_IATA_MAP[key]

    # Fallback: return the original text uppercased so it's obvious it's unresolved
    return text.strip().upper()


def load_boxes_config(config_path = "boxes_config.json") -> Dict[str, Any]:
    """Load boxes configuration from JSON file or dictionary"""
    if isinstance(config_path, dict):
        return config_path
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
            return config.get('templates', {})
    except FileNotFoundError:
        raise FileNotFoundError(f"Configuration file '{config_path}' not found.")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in configuration file: {e}")

def extract_email(text: str) -> Optional[str]:
    """Extract email address from text"""
    # Prefer strings labelled "EMAIL: ", forgiving missing .com domains often chopped by OCR
    m = re.search(r'EMAIL\s*:?\s*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+)', text, re.IGNORECASE)
    if m:
        return m.group(1).strip()
        
    # Fallback generic pattern
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    match = re.search(email_pattern, text)
    return match.group(0) if match else None

def extract_phone(text: str) -> Optional[str]:
    """Extract phone number from text."""
    phone_pattern = r'(?:PHONE|TEL|Phone|Tel|PH|Ph)\s*:?\s*([+\d()\-][+\d\s()\-]{3,30})'
    match = re.search(phone_pattern, text, re.IGNORECASE)
    if match:
        return match.group(1).strip().rstrip(' -')
        
    # Fallback missing prefix, but demanding typical phone structure
    # e.g. "91-120-4319911" or "+1-800-555-1234"
    # To avoid accidentally catching PIN codes, ensure it's long enough and has formatting dashes
    fallback_pattern = r'(?<!\d)(?:(?:\+|00)?\d{1,3}[-.\s])?(?:\(?\d{2,4}\)?[-.\s])?\d{3,4}[-.\s]\d{4,9}(?!\d)'
    match = re.search(fallback_pattern, text)
    if match:
        cand = match.group(0).strip()
        # Ensure it has at least 8 digits
        if len(re.sub(r'\D', '', cand)) >= 8:
            return cand
            
    return None

def extract_fax(text: str) -> Optional[str]:
    """Extract fax number from text"""
    fax_pattern = r'(?:FAX|Fax)\s*:\s*([+\d\s()-]+)'
    match = re.search(fax_pattern, text, re.IGNORECASE)
    return match.group(1).strip() if match else None

def extract_eori(text: str) -> Optional[str]:
    """Extract EORI number from text."""
    eori_pattern = r'(?:EORI|Eori)\s*:?\s*([A-Z]{2}[A-Z0-9]{6,})'
    match = re.search(eori_pattern, text, re.IGNORECASE)
    if match:
        return f"EORI : {match.group(1).strip()}"
    return None

def extract_pin(text: str, country: str = None) -> Optional[str]:
    """
    Extract postal/PIN code from address text.
    Tier 1: Country-specific pattern
    Tier 2: Contextual numeric match
    Tier 3: Continent-scoped sweep
    Tier 4: Generic numeric fallback
    """
    # Tier 1: country known and has a compiled pattern
    if country and country in POSTCODE_PATTERNS:
        pat = POSTCODE_PATTERNS[country]
        if pat is None:
            # Country explicitly has no postcode (UAE) → skip to Tier 2
            pass
        else:
            m = pat.search(text)
            if m:
                return m.group(1).strip()

    # Tier 2: digit run immediately after a separator — high-confidence location signal
    # e.g. "GURUGRAM – 122016 HARYANA" or "INDIA - 370201"
    contextual = re.search(r'(?<!\d)[-–,]\s*(\d{4,7})\b(?!\s*[-–]\d)', text)
    if contextual:
        candidate = contextual.group(1)
        # Reject if it looks like a year or phone segment
        if not re.match(r'^(19|20)\d{2}$', candidate):
            return candidate

    # Tier 3: if country is unrecognised, try all POSTCODE_PATTERNS
    # Stop at first match — patterns are ordered by specificity (alphanumeric before pure numeric)
    if not country or country not in GEO_DATA:
        for _country, pat in POSTCODE_PATTERNS.items():
            if pat is None:
                continue
            m = pat.search(text)
            if m:
                return m.group(1).strip()

    # Tier 4: absolute last resort — any 4-7 digit run not preceded by another digit
    # Reject years (19xx, 20xx) and known charge-amount patterns
    generic = re.search(r'(?<!\d)\b(\d{4,7})\b(?!\d)', text)
    if generic:
        candidate = generic.group(1)
        if not re.match(r'^(19|20)\d{2}$', candidate):
            return candidate

    return None

def extract_country(text: str) -> Optional[str]:
    """Extract country from address"""
    for country_key, pattern in COUNTRY_PATTERNS.items():
        if pattern.search(text):
            return country_key

    us_city_state_zip = r'\b[A-Z][A-Z\s]+,\s*[A-Z]{2}\s+\d{5}\b'
    if re.search(us_city_state_zip, text):
        return 'USA'

    return None

def _strategy_generic(address: str) -> Optional[str]:
    """
    Fallback for any unrecognised country or failed strategy.
    Tries three sub-approaches in order:

    A) Last clean UPPERCASE token before a digit run or country name
    B) Comma-separated segment scan (right to left, skip noise words)
    C) None
    """
    # Sub-approach A: find a word run before a postcode-like digit cluster
    m = re.search(r'([A-Z][A-Z\s]{2,}?)\s*[,.]?\s*\d{4,6}', address)
    if m:
        candidate = STREET_NOISE.sub('', m.group(1)).strip()
        if len(candidate) > 2:
            return candidate

    # Sub-approach B: comma segments, right to left, reject noise
    segments = [s.strip() for s in address.split(',') if s.strip()]
    for seg in reversed(segments[-4:]):
        if re.match(r'^[A-Z][A-Z\s]{2,}$', seg) and not STREET_NOISE.search(seg):
            return seg

    return None

def _strategy_city_state_zip(address: str, country: str) -> Optional[str]:
    """Matches: CITY, ST 12345  or  CITY ST 12345"""
    code_pat = CODE_PATTERNS.get(country)
    if code_pat:
        # Walk backwards from state code
        m = re.search(r'([A-Z][A-Z\s]+?),?\s*' + code_pat.pattern, address)
        if m:
            candidate = STREET_NOISE.sub('', m.group(1)).strip().rstrip(',')
            if candidate:
                return candidate
    return _strategy_generic(address)   # ← always has a fallback

def _strategy_postcode_then_city(address: str, postcode_pat) -> Optional[str]:
    """Matches: 12345 CITY  (postcode precedes city on same line)"""
    if postcode_pat:
        m = re.search(postcode_pat.pattern + r'\s+(?P<city>[A-Z][A-Z\s\-]+)', address)
        if m:
            candidate = STREET_NOISE.sub('', m.group('city')).strip()
            if candidate:
                return candidate
    return _strategy_generic(address)

def _strategy_before_postcode(address: str, postcode_pat, dotted: bool = False) -> Optional[str]:
    """
    Matches: CITY POSTCODE  or  CITY. POSTCODE
    Also handles UK multi-line: last text line before the postcode line.
    """
    if postcode_pat:
        sep = r'[.\s]+' if dotted else r'\s+'
        m = re.search(r'([A-Z][A-Z\s\-]+?)' + sep + postcode_pat.pattern, address)
        if m:
            candidate = STREET_NOISE.sub('', m.group(1)).strip().rstrip('.')
            if candidate:
                return candidate
        # Multi-line fallback: city is the last non-postcode line
        lines = [l.strip() for l in address.split('\n') if l.strip()]
        for line in reversed(lines):
            if postcode_pat.search(line):
                continue   # skip the postcode line itself
            if re.match(r'^[A-Z][A-Z\s\-]+$', line) and not STREET_NOISE.search(line):
                return line
    return _strategy_generic(address)

def _strategy_state_then_pin(address: str, country: str) -> Optional[str]:
    """
    Matches:
      GURUGRAM – 122016 HARYANA   → GURUGRAM
      AHMEDABAD, INDIA - 370201   → AHMEDABAD
    Rejects candidates that are themselves state/noise words.
    """
    state_pat = STATE_PATTERNS.get(country)

    # Pattern A: CITY – PIN STATE
    m = re.search(r'([A-Z][A-Z\s]+?)\s*[–\-]\s*\d{4,6}\s+', address)
    if m:
        candidate = m.group(1).strip()
        if state_pat and state_pat.fullmatch(candidate.strip()):
            pass   # it's a state name, not a city — keep searching
        elif not STREET_NOISE.search(candidate) and len(candidate) > 2:
            return candidate

    # Pattern B: CITY, COUNTRY
    if state_pat:
        m2 = re.search(r'([A-Z][A-Z\s]+?),\s*' + '|'.join(
            re.escape(p.lstrip(r'\b').rstrip(r'\b'))
            for p in GEO_DATA.get(country, {}).get('country_patterns', [])
        ), address, re.IGNORECASE)
        if m2:
            candidate = STREET_NOISE.sub('', m2.group(1)).strip()
            if not STREET_NOISE.search(candidate) and len(candidate) > 2:
                return candidate

    return _strategy_generic(address)

def _strategy_state_anchor(address: str, country: str) -> Optional[str]:
    """State name IS the city (Dubai, Abu Dhabi, etc.)"""
    state_pat = STATE_PATTERNS.get(country)
    if state_pat:
        m = state_pat.search(address)
        if m:
            return m.group(1).strip()
    return _strategy_generic(address)

def extract_city(address: str, country: str = None) -> Optional[str]:
    """
    Extract city from address text using country-specific strategies.
    Priority: structured regex patterns first, state-anchor fallback second.
    """
    if not address:
        return None

    # ── Step 1: City list direct match (highest confidence, any country) ──────
    if country and country in CITY_PATTERNS and CITY_PATTERNS[country]:
        m = CITY_PATTERNS[country].search(address)
        if m:
            return m.group(1).strip()
    elif not country:
        # If country isn't known, sweep major global cities just in case
        for c, pat in CITY_PATTERNS.items():
            if pat:
                m = pat.search(address)
                if m:
                    return m.group(1).strip()

    # ── Step 2: Read city_strategy from GEO_DATA ──────────────────────────────
    strategy = GEO_DATA.get(country, {}).get('city_strategy', 'generic')
    postcode_pat = POSTCODE_PATTERNS.get(country)

    if strategy == 'city_state_zip':
        return _strategy_city_state_zip(address, country)

    elif strategy == 'postcode_then_city':
        return _strategy_postcode_then_city(address, postcode_pat)

    elif strategy in ('before_postcode', 'before_postcode_dotted'):
        return _strategy_before_postcode(address, postcode_pat, dotted=(strategy == 'before_postcode_dotted'))

    elif strategy == 'state_then_pin':
        return _strategy_state_then_pin(address, country)

    elif strategy == 'state_anchor':
        return _strategy_state_anchor(address, country)

    # ── Step 3: Generic fallback (unknown country or strategy miss) ───────────
    return _strategy_generic(address)

def extract_state(text: str, country: Optional[str]) -> Optional[str]:
    if not text or not country:
        return None
    key = country.upper()
    if key not in STATE_PATTERNS:
        return None
    # Try full state name first
    state_pat = STATE_PATTERNS.get(key)
    if state_pat:
        m = state_pat.search(text)
        if m:
            return m.group(1).strip().upper()
    # Fallback to 2/3-letter codes
    code_pat = CODE_PATTERNS.get(key)
    if code_pat:
        m = code_pat.search(text)
        if m:
            return m.group(1).strip().upper()
    return None

def clean_address(text: str) -> str:
    cleaned = re.sub(r'\|', ' ', text)                          # strip PDF border artifacts
    cleaned = re.sub(r'OFFICE\s*:\s*[\d\s\-]+', '', cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r'(?:EXT|CELL)\s*[\dA-Z\s\-:]+', '', cleaned, flags=re.IGNORECASE)
    for pattern in CLEAN_ADDRESS_PATTERNS:
        cleaned = pattern.sub('', cleaned)
    cleaned = re.sub(r',\s*,', ',', cleaned)
    cleaned = cleaned.strip().strip(',')
    cleaned = re.sub(r'\s+', ' ', cleaned)
    return cleaned.strip()

def normalize_text(text: str) -> str:
    """Normalize text by replacing newlines with spaces and cleaning whitespace"""
    text = text.replace('\n', ' ')
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def transform_address_box(text: str) -> Dict[str, Any]:
    """Transform address box data."""
    text = re.sub(r'\|', ' ', text) # strip PDF border artifacts at the very start
    SKIP_PREFIXES = ("ATTN:", "ATTN :", "ATTENTION:", "EORI", "SHIPPER'S NAME AND ADDRESS", "SHIPPER'S ACCOUNT NUMBER", "CONSIGNEE'S NAME AND ADDRESS", "CONSIGNEE'S ACCOUNT NUMBER")

    raw_lines = [l.strip() for l in text.split('\n') if l.strip()]

    cleaned_lines = []
    for line in raw_lines:
        cl = clean_address(line)
        if not cl:
            continue
        if any(cl.upper().startswith(p) for p in SKIP_PREFIXES):
            continue
        cleaned_lines.append(cl)

    country     = extract_country(text)
    entity_name = cleaned_lines[0] if cleaned_lines else ''
    address_lines = cleaned_lines[1:] if len(cleaned_lines) > 1 else []
    address_str   = ', '.join(address_lines)
    address_str   = re.sub(r',\s*,', ',', address_str).strip().strip(',').strip()
    
    city  = extract_city(address_str, country)
    state = extract_state(address_str, country)
    pin   = extract_pin(text, country)

    # Strip extracted fields from address_str to leave only street details
    clean_addr = address_str

    # 1. Remove PIN
    if pin:
        clean_addr = re.sub(
            r'[\s,–\-]*' + re.escape(pin) + r'[\s,–\-]*',
            ' ', clean_addr, flags=re.IGNORECASE
        )

    # 2. Remove CITY
    if city:
        clean_addr = re.sub(
            r'[\s,–\-]*\b' + re.escape(city) + r'\b[\s,–\-]*',
            ' ', clean_addr, flags=re.IGNORECASE
        )

    # 3. Remove STATE
    if state:
        # Avoid stripping if state is also part of city (e.g. "NEW DELHI")
        # but usually we want to strip the specific state mention.
        clean_addr = re.sub(
            r'[\s,–\-]*\b' + re.escape(state) + r'\b[\s,–\-]*',
            ' ', clean_addr, flags=re.IGNORECASE
        )

    # 4. Remove COUNTRY
    if country:
        clean_addr = re.sub(
            r',?\s*\b' + re.escape(country) + r'\b',
            '', clean_addr, flags=re.IGNORECASE
        )

    # 5. Final cleanup
    clean_addr = re.sub(r',\s*,+', ',', clean_addr)
    clean_addr = re.sub(r'[,\s–\-]+$|^[,\s–\-]+', '', clean_addr)
    clean_addr = re.sub(r'\s{2,}', ' ', clean_addr).strip()

    # Remove any special characters (keep only alphanumeric and spaces)
    clean_name = re.sub(r'[^a-zA-Z0-9\s]', ' ', entity_name)
    clean_name = re.sub(r'\s+', ' ', clean_name).strip()

    clean_addr = re.sub(r'[^a-zA-Z0-9\s]', ' ', clean_addr)
    clean_addr = re.sub(r'\s+', ' ', clean_addr).strip()

    return {
        'full_details': ' '.join(cleaned_lines),
        'name':    clean_name,
        'address': clean_addr,
        'city':    city,
        'state':   state,
        'country': country,
        'pin':     pin,
        'phone':   extract_phone(text),
        'fax':     extract_fax(text),
        'eori':    extract_eori(text),
        'email':   extract_email(text)
    }

def transform_flight_routing(text_data: str) -> List[Dict[str, Any]]:
    """Transform flight routing data."""
    airport_pattern = r'\b[A-Z]{3}\b'
    flight_pattern = r'\b[A-Z]{2,3}[-\s]?\d{1,6}[A-Z]{0,2}\b'
    date_pattern = r'\d{2}-[A-Z]{3}-\d{4}|\d{2}-[A-Za-z]{3}|\d{1,2}(?:st|nd|rd|th)[A-Za-z]{3,}|\d{2}/\d{2}/\d{4}'

    # These words will be blocked from being identified as airports
    LABEL_WORDS = {
        'TO', 'BY', 'FIRST', 'CARRIER', 'ROUTING', 'AND', 'DESTINATION',
        'AIRPORT', 'OF', 'REQUESTED', 'FLIGHT', 'DATE', 'FLIGHT/DATE', 
        'AIR', 'JET', 'FLY', 'SKY', 'SUN', 'BAY', 'RED', 'ONE', 'ALL', 
        'KLM', 'JAL', 'THE', 'FOR', 'LOT'
    }

    results = []
    # Split input into blocks (separated by empty lines)
    blocks = [b.strip() for b in text_data.strip().split('\n\n') if b.strip()]

    for block in blocks:
        lines = block.split('\n')
        all_airports = []
        
        for line in lines:
            # 1. Find all 3-letter uppercase words
            raw_found = re.findall(airport_pattern, line)
            
            # 2. Filter out words that are in the LABEL_WORDS set
            found = [code for code in raw_found if code.upper() not in LABEL_WORDS]
            
            # 3. If we found valid airports, save them and stop looking in this block
            if found:
                all_airports = found
                break

        transit_airports = all_airports
        raw_flights = re.findall(flight_pattern, block)
        dates = re.findall(date_pattern, block)

        from datetime import datetime
        current_year = datetime.now().year

        def normalize_routing_date(d):
            # If the date doesn't already have a 4-digit year, append the current one
            if not re.search(r'\d{4}$', d):
                return f"{d}-{current_year}"
            return d

        # Pair flights with dates
        flights_list = [
            {"flight_number": re.sub(r'[-\s]', '', f), "date": normalize_routing_date(d)}
            for f, d in zip(raw_flights, dates)
        ]

        results.append({
            "transit_airports": transit_airports,
            "flights": flights_list
        })

    return results

def extract_hs_codes(text: str) -> List[str]:
    """Extract HS codes from text"""
    hs_pattern = r'\b\d{6,8}\b'
    return re.findall(hs_pattern, text)

def extract_dimensions(text: str) -> List[Dict[str, Any]]:
    """Extract dimensions and their counts from text."""
    dimensions = []
    seen = set()

    SEP = r'\s*[xX\*]\s*'

    patterns = [
        (r'\(\s*(\d+)\s*\)\s*(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)', 'count_first'),
        (r'(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)\s*\(\s*(\d+)\s*\)', 'count_last'),
        (r'(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)\s*=\s*(\d+)', 'count_last'),
        (r'(\d+)\s*=\s*(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)', 'count_first'),
        (r'(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)\s*/\s*(\d+)', 'count_last'),
        (r'(\d+)\s*/\s*(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)', 'count_first'),
        (r'(\d+)\s*\*\s*(\d+)\s*\*\s*(\d+)\s*\*\s*(\d+)', 'count_last'),
    ]

    for pattern, mode in patterns:
        for m in re.finditer(pattern, text, re.IGNORECASE):
            g = m.groups()
            if mode == 'count_first':
                count, l, w, h = g
            else:
                l, w, h, count = g
            dim_str = f"{l}X{w}X{h}"
            key = (dim_str, int(count))
            if key not in seen:
                seen.add(key)
                dimensions.append({'dimension': dim_str, 'count': int(count)})

    # Fallback: plain NxNxN with no count
    for m in re.finditer(r'(\d+)' + SEP + r'(\d+)' + SEP + r'(\d+)', text, re.IGNORECASE):
        l, w, h = m.groups()
        dim_str = f"{l}X{w}X{h}"
        if not any(d['dimension'] == dim_str for d in dimensions):
            dimensions.append({'dimension': dim_str, 'count': 1})

    return dimensions

def transform_description(text: str) -> Dict[str, Any]:
    hs_codes   = extract_hs_codes(text)
    dimensions = extract_dimensions(text)

    description = normalize_text(text)

    # Strip HS/HSN CODE labels and following numbers (e.g. "HS CODE: 6205", "HSN CODE: 8201", "HS CODE 123")
    description = re.sub(
        r'\b(?:HS|HSN)\s*CODE\s*:?\s*[\d\s\.]*', '', description, flags=re.IGNORECASE
    )

    # Strip individual HS code numbers that remain
    for hs in hs_codes:
        description = re.sub(r'\b' + re.escape(hs) + r'\b', '', description)

    # Strip DIMS/DIM block in all known formats:
    # "DIMS-36X32X25=125 50X30X47=18"
    # "DIM(CMS): 59X38X15 (17), 59X38X10 (3), 59X38X30 (9)"
    # "DIMENSIONS: ..."
    description = re.sub(
        r'\bDIMS?\s*(?:\([^)]*\))?\s*[-:]?\s*'   # DIMS- / DIM(CMS): / DIMENSIONS:
        r'(?:'
            r'\d+\s*[Xx*]\s*\d+\s*[Xx*]\s*\d+'   # NxNxN dimension
            r'(?:\s*[=()\d,\s]*)?'                 # followed by count/separators
        r')+'                                       # one or more dimension entries
        r'[\d,\s()\-Xx*=]*',                       # trailing count debris
        '', description, flags=re.IGNORECASE
    )

    # Strip any remaining standalone dimension expressions not caught above
    # Format: NxNxN (N)  or  NxNxN=N  or  N/NxNxN  or  (N)NxNxN
    description = re.sub(
        r'[\(\d]*\d+\s*[Xx*]\s*\d+\s*[Xx*]\s*\d+[\s=\/\(\)]*\d*\s*[\),]?',
        '', description, flags=re.IGNORECASE
    )

    # Strip VOL WT  — "VOL WT 931.72"
    description = re.sub(
        r'\bVOL\s*WT\s*[\d.]+', '', description, flags=re.IGNORECASE
    )

    # Final cleanup — remove orphaned punctuation and collapse spaces
    description = re.sub(r'\s*,\s*,+', ',', description)
    description = re.sub(r'^[\s,:\-]+|[\s,:\-]+$', '', description)
    description = re.sub(r'\s{2,}', ' ', description).strip()

    # Limit to 70 characters
    description = description[:70].strip()

    return {
        'description': description,
        'hs_codes':    hs_codes,
        'dimensions':  dimensions,
        'raw_text':    normalize_text(text),
    }

def transform_piece_weight(text: str) -> Dict[str, Any]:
    """Transform piece and weight data."""
    text = normalize_text(text)
    text = re.sub(r'(\d),(\d)', r'\1\2', text)
    parts = text.split()

    def is_number(s: str) -> bool:
        try:
            float(s)
            return True
        except ValueError:
            return False

    no_of_pieces  = int(float(parts[0])) if len(parts) > 0 and is_number(parts[0]) else 0
    gross_weight  = float(parts[1])      if len(parts) > 1 and is_number(parts[1]) else 0.0

    numeric_tail = [float(p) for p in parts[2:] if is_number(p)]
    chargeable_weight = numeric_tail[0] if len(numeric_tail) > 0 else 0.0
    rate              = numeric_tail[1] if len(numeric_tail) > 1 else 0.0
    total_charge      = numeric_tail[2] if len(numeric_tail) > 2 else 0.0

    rate_class_parts = []
    for p in parts[2:]:
        if is_number(p):
            break
        rate_class_parts.append(p)
    rate_class = ' '.join(rate_class_parts)

    return {
        'no_of_pieces':      no_of_pieces,
        'gross_weight':      gross_weight,
        'rate_class':        rate_class,
        'chargeable_weight': chargeable_weight,
        'rate':              rate,
        'total_charge':      total_charge,
    }

def transform_awb_number(text: str) -> str:
    """Transform AWB number."""
    text = normalize_text(text)
    if re.match(r'^\d{3}-\d+$', text.strip()):
        return text.strip()
    parts = text.split()
    if len(parts) >= 3:
        return f"{parts[0]}-{parts[2]}"
    match = re.search(r'\d{3}-\d{5,10}', text)
    return match.group(0) if match else text

def process_box(box_name: str, text: str) -> Any:
    """Process extracted text based on box name"""
    if box_name in ['shipper', 'consignee']:
        return transform_address_box(text)
    elif box_name == 'transit':
        return transform_flight_routing(text)
    elif box_name == 'cargo':
        return transform_description(text)
    elif box_name == 'piece_weight':
        return transform_piece_weight(text)
    elif box_name == 'awb_number':
        return transform_awb_number(text)
    elif box_name in ['departure', 'destination']:
        return resolve_iata(normalize_text(text))
    else:
        return normalize_text(text)
# hello
def extract_all_boxes(pdf_path: str, template_name: str,
                     config_path = "boxes_config.json",
                     page_num: int = 0) -> Dict[str, Any]:
    """Extract and process all boxes from PDF for a given template."""
    if isinstance(config_path, dict):
        if template_name in config_path:
            templates = config_path
        else:
            templates = {template_name: config_path}
    else:
        templates = load_boxes_config(config_path)

    if template_name not in templates:
        raise ValueError(
            f"Template '{template_name}' not found in configuration. "
            f"Available templates: {', '.join(templates.keys()) if isinstance(templates, dict) else ''}"
        )

    template = templates[template_name]
    result = {}

    with pdfplumber.open(pdf_path) as pdf:
        page = pdf.pages[page_num]
        for box_name, bbox in template.items():
            try:
                # Use crop instead of within_bbox for better reliability with tight coordinates
                text = page.crop(tuple(bbox)).extract_text() or ''
            except Exception as e:
                print(f"Warning: Failed to extract '{box_name}' with bbox {bbox}: {e}")
                text = ''
            result[box_name] = process_box(box_name, text)

    return result

def main():
    """Main function to handle command-line arguments"""
    if len(sys.argv) < 3:
        print("Usage: python pdf_extractor.py <pdf_file> <template_name> [config_file] [page_number]")
        print("\nExamples:")
        print("  python pdf_extractor.py temp.pdf ksr")
        print("  python pdf_extractor.py temp.pdf ksr_house")
        print("  python pdf_extractor.py temp.pdf ksr boxes_config.json")
        print("  python pdf_extractor.py temp.pdf ksr boxes_config.json 0")
        sys.exit(1)

    pdf_file = sys.argv[1]
    template_name = sys.argv[2]
    config_file = sys.argv[3] if len(sys.argv) > 3 else "boxes_config.json"
    page_num = int(sys.argv[4]) if len(sys.argv) > 4 else 0

    if not Path(pdf_file).exists():
        print(f"Error: PDF file '{pdf_file}' not found.")
        sys.exit(1)

    try:
        result = extract_all_boxes(pdf_file, template_name, config_file, page_num)
        print(json.dumps(result, indent=2))
    except Exception as e:
        print(f"Error processing PDF: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(1)

if __name__ == "__main__":
    main()